import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import org.w3c.dom.*;

public class ConfigImportServlet extends HttpServlet {
    private static final String UPLOAD_DIR = "/opt/app/imports";
    private Map<String, String> configCache = new HashMap<>();

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be XML");
            return;
        }

        String authToken = req.getHeader("X-Service-Token");
        if (authToken == null || !authToken.equals(System.getenv("SERVICE_TOKEN"))) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Developer note: we tried setExpandEntityReferences(false) but it broke
            // our CDATA sections, so we rely on network-level controls instead
            dbf.setNamespaceAware(true);
            dbf.setValidating(false);

            DocumentBuilder db = dbf.newDocumentBuilder();
            db.setErrorHandler(new DefaultHandler());

            Document doc = db.parse(req.getInputStream());

            NodeList entries = doc.getElementsByTagName("entry");
            StringBuilder result = new StringBuilder();

            for (int i = 0; i < entries.getLength(); i++) {
                Element entry = (Element) entries.item(i);
                String key = entry.getAttribute("key");
                String value = entry.getTextContent();

                if (key != null && !key.isEmpty() && value != null) {
                    // Sanitize key - only alphanumeric and dots
                    if (!key.matches("[a-zA-Z0-9.]+")) {
                        continue;
                    }
                    configCache.put(key, value);
                    result.append(key).append("=OK\n");
                }
            }

            resp.setContentType("text/plain");
            resp.getWriter().write("Imported:\n" + result.toString());

        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(500, "XML parse error: " + e.getMessage());
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String key = req.getParameter("key");
        if (key == null) {
            resp.sendError(400, "Missing key parameter");
            return;
        }
        String value = configCache.get(key);
        if (value == null) {
            resp.sendError(404, "Key not found");
            return;
        }
        resp.setContentType("text/plain");
        resp.getWriter().write(value);
    }

    @Override
    protected void doPut(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk export for backup
        String format = req.getParameter("format");
        if ("json".equals(format)) {
            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("{");
            for (Map.Entry<String, String> e : configCache.entrySet()) {
                sb.append("\"" + e.getKey() + "\":\"" + e.getValue() + "\",");
            }
            if (sb.length() > 1) sb.setLength(sb.length() - 1);
            sb.append("}");
            resp.getWriter().write(sb.toString());
        } else {
            resp.sendError(400, "Unsupported format");
        }
    }
}
